[TestCase]
public void A_version_1_file_keeps_its_volume_and_language()
{
    File.WriteAllText(_path, """{"volume_db": -6.0, "language": "de"}""");
    SettingsData data = new SettingsStore(_path).Read();
    AssertThat(data.Volume).IsEqualApprox(Godot.Mathf.DbToLinear(-6.0), 0.001);
    AssertThat(data.Locale).IsEqual("de");
    AssertThat(data.Version).IsEqual(SettingsStore.Version);
}

